function sampleAttachments(){return SLOTS.flatMap((slot,i)=>['Alpha','Bravo'].map((n,j)=>({id:`sample-${i}-${j}`,slot,name:`Sample ${slot} ${n}`,status:'sample',source:''})));}
function availableAttachments(weapon,demo){return [...weapon.attachments,...(demo&&!['Launcher','Melee'].includes(weapon.category)?sampleAttachments():[])];}

